/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_PARTY_ORGANISATION_PROFILE
   anchor      : HUB_PARTY   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 2 emitted of 3 (one per source view AND run)
   runs        : 2 -- opus_health_legacy_v4, opus_health_v2
   payload     : 5 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PARTY_HK
   hashdiff    : SAT_PARTY_ORGANISATION_PROFILE_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   BESPOKE LAYER dual_feed_satellite_loader (s6.5): BOTH runs write this satellite.
   The standard satellite layer unions feeders that are disjoint by construction,
   which is the assumption two independent writers break.
   CROSS-RUN RECONCILIATION, DECLARED (carve-out ratified by the mapping counterparty):
   this satellite's anchor is one of the shared objects written by BOTH runs, whose two
   identifier registries are UNRECONCILED. The declared source precedence below is a VALUE
   CHOICE APPLIED TO ROWS THAT MAY REPRESENT TWO UNRECONCILED POPULATIONS -- two writers may
   be describing one entity, or two different parties colliding in one key space, and which
   it is cannot be settled from the map, the model or the SQL.
   WHY THE SCOPE IS EVERY SHARED OBJECT AND NOT A LOW-OVERLAP SUBSET: a hub-level
   business-key-column overlap cannot see the hazard at any threshold. HUB_PARTY's overlap
   of three is IMD_CODE, PART_ID and RM_CODE, all intermediary-side; on the member/customer
   population the overlap is ZERO. The figure is unstable too -- collapsing underscores moves
   it from three to five.
   WHY DECLARE RATHER THAN REFUSE: the choice is made on ASYMMETRY. A DECLARED CONFLICT IS
   RECOVERABLE; A WRONG MERGE IS NOT, AFTER LOAD. That is the justification, not a
   preference.
   The subordinate writer and its registry are NAMED below so the loss is COUNTABLE.
   A load-time assertion in models/assertions/ counts the hash keys actually written by both
   runs. Until it runs, whether the precedence EVER fires is UNKNOWN, not zero.
     SUBORDINATE WRITER on MSME_INDICATOR: run opus_health_legacy_v4, 1 writer(s), registry/ies HUB_PARTY_BK__HOSID -- its value is DISCARDED wherever opus_health_v2 also writes the same key
   DECLARED SOURCE PRECEDENCE -- 1 attribute(s) are written by BOTH runs.
   Never a key change and never RECORD_SOURCE in a key: either would
   silently alter grain. Precedence is a VALUE choice, reversible by reload:
     MSME_INDICATOR                               opus_health_v2 > opus_health_legacy_v4
   INTRA-RUN FAN-IN, 1 attribute/run pair(s) with more than one writer, of
   which 0 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     INDUSTRY_DESCRIPTION                   opus_health_legacy_v4  2 writer(s), of which 1 UNDISCRIMINATED (0 separated by a resolved instance, 1 by redundant_of)
*/

with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , cast(null as varchar) as INDUSTRY_DESCRIPTION
        , cast(null as varchar) as MSME_INDICATOR
        , LEGAL_CONST as LEGAL_CONSTITUTION_CODE
        , cast(null as varchar) as GROUP_NAME
        , cast(null as varchar) as MSME_CATEGORY
        , 'BJAZ_HM_HOSPITAL_MASTER_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master_extn') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__IMD_CODE))) as HUB_PARTY_HK
        , cast(null as varchar) as INDUSTRY_DESCRIPTION
        , SME_YN as MSME_INDICATOR
        , cast(null as varchar) as LEGAL_CONSTITUTION_CODE
        , CORPORATE_NAME as GROUP_NAME
        , SMESIZE as MSME_CATEGORY
        , 'BJAZ_ENROLL_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_pol_dtls') }}
    where (nullif(trim(IMD_CODE),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then INDUSTRY_DESCRIPTION end) as INDUSTRY_DESCRIPTION,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then MSME_INDICATOR end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MSME_INDICATOR end)) as MSME_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LEGAL_CONSTITUTION_CODE end) as LEGAL_CONSTITUTION_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then GROUP_NAME end) as GROUP_NAME,
        max(case when SOURCE_RUN = 'opus_health_v2' then MSME_CATEGORY end) as MSME_CATEGORY,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when INDUSTRY_DESCRIPTION is not null or MSME_INDICATOR is not null or LEGAL_CONSTITUTION_CODE is not null or GROUP_NAME is not null or MSME_CATEGORY is not null
                     then md5(upper(coalesce(cast(INDUSTRY_DESCRIPTION as varchar), '') || '|' || coalesce(cast(MSME_INDICATOR as varchar), '') || '|' || coalesce(cast(LEGAL_CONSTITUTION_CODE as varchar), '') || '|' || coalesce(cast(GROUP_NAME as varchar), '') || '|' || coalesce(cast(MSME_CATEGORY as varchar), '')))
                end as SAT_PARTY_ORGANISATION_PROFILE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_ORGANISATION_PROFILE_HASHDIFF is not null
